import numpy as np

def expected_max_sharpe(n_trials, n_obs, seed, sims):
    rng = np.random.default_rng(seed)
    se = np.sqrt(252 / n_obs)
    sharpes = rng.standard_normal((sims, n_trials)) * se
    return round(float(sharpes.max(axis=1).mean()), 2)

